rainbow_animation.code:
void matrix_rainbow(int offset) {
    for (int row = 0; row < MATRIX_ROWS; row++) {
        for (int col = 0; col < MATRIX_COLS; col++) {
            int color_idx = (offset < 16) ? row*8+col+offset*8 : ...;
            color_idx = color_idx % 192;
            matrix_set_pixel(row, col, gradient_colors[color_idx][0], ...);
        }
    }
}

hsv_to_rgb.code:
rgb_color_t hsv_to_rgb(uint16_t h, uint8_t s, uint8_t v) {
    uint8_t region = h / 60, remainder = (h - region*60) * 255 / 60;
    p = (v * (255 - s)) / 255;
    q = (v * (255 - (s * remainder) / 255)) / 255;
    t = (v * (255 - (s * (255 - remainder)) / 255)) / 255;
    switch (region) { case 0: rgb.r=v; rgb.g=t; rgb.b=p; break; ... }
}

text_scroll.code:
void text_scroll(const char* text) {
    matrix_clear();
    int x_pos = scroll_offset;
    for (int i = 0; i < len; i++) {
        draw_char_at(text[i], x_pos);
        x_pos += font_get_char_width(text[i]) + CHAR_SPACING;
    }
    matrix_refresh();
    scroll_offset--;
    if (scroll_offset < -text_width) scroll_offset = MATRIX_COLS;
}

